      - uses: actions/setup-python@v7
        with:
          python-version: '3.12'
      - name: Install pinned native inspection toolchain
        run: python scripts/release/sevenzip.py install
      - uses: sigstore/cosign-installer@v4.1.3
      - uses: actions/download-artifact@v8
        with:
          pattern: mesh-talk-*
          merge-multiple: true
          path: workflow-assets
      - name: Verify workflow artifacts
        run: bash scripts/release/verify-release.sh workflow-assets "$ARTIFACT_TAG" "$RELEASE_VERSION" "$SOURCE_REPO" "$SOURCE_REF" "$SOURCE_SHA"
      - name: Recheck draft state immediately before the single upload
        if: startsWith(github.ref, 'refs/tags/') || needs.preflight.outputs.nightly == 'true'
        run: node scripts/release/release-state.mjs guard "$ARTIFACT_TAG"
      - name: Pin immutable Nightly tag to the verified source
        if: needs.preflight.outputs.nightly == 'true'
        run: node scripts/release/prepare-nightly.mjs
      - name: Prepare release notes
        if: startsWith(github.ref, 'refs/tags/') || needs.preflight.outputs.nightly == 'true'
        run: node scripts/release/render-notes.mjs
      - name: Upload all verified platforms to the draft
        if: startsWith(github.ref, 'refs/tags/') || needs.preflight.outputs.nightly == 'true'
        uses: softprops/action-gh-release@v3
        with:
          draft: true
          prerelease: ${{ needs.preflight.outputs.nightly == 'true' }}
          make_latest: false
          target_commitish: ${{ github.sha }}
          overwrite_files: ${{ needs.preflight.outputs.nightly != 'true' }}
          tag_name: ${{ needs.preflight.outputs.tag }}
          body_path: release_notes.md
          generate_release_notes: false
          files: workflow-assets/*
      - name: Verify actual draft release assets
        if: startsWith(github.ref, 'refs/tags/') || needs.preflight.outputs.nightly == 'true'
        run: |
          mkdir draft-assets
          gh release download "$ARTIFACT_TAG" --repo "$SOURCE_REPO" --dir draft-assets
          bash scripts/release/verify-release.sh draft-assets "$ARTIFACT_TAG" "$RELEASE_VERSION" "$SOURCE_REPO" "$SOURCE_REF" "$SOURCE_SHA"
          node scripts/release/release-state.mjs record "$ARTIFACT_TAG" draft-assets workflow-assets
      - name: Recheck source and publish the verified Nightly draft
        if: needs.preflight.outputs.nightly == 'true'
        run: |
          node scripts/release/check-source-checks.mjs "$SOURCE_REPO" "$SOURCE_SHA"
          node scripts/release/release-state.mjs verify "$ARTIFACT_TAG" draft-assets
          node scripts/release/release-state.mjs publish "$ARTIFACT_TAG"
      - name: Record verification evidence
        run: |
          printf 'Verified source: %s\nArtifact tag: %s\nVersion: %s\n' "$SOURCE_SHA" "$ARTIFACT_TAG" "$RELEASE_VERSION" > verification.txt
          sha256sum workflow-assets/* >> verification.txt
          if [[ -d draft-assets ]]; then sha256sum draft-assets/* >> verification.txt; fi
          cat verification.txt >> "$GITHUB_STEP_SUMMARY"
      - uses: actions/upload-artifact@v7
        with:
          name: verified-release-evidence
          path: |
            verification.txt
            verified-draft.json
          if-no-files-found: error

